import 'dart:io';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:nut_manager_app/services/scanner_service.dart';
import 'package:path_provider/path_provider.dart';

/// AT1.2: feeds each generated barcode fixture image (EQ-P1, generated by
/// tool/generate_barcode_fixtures.py) to the real ML Kit decoder via
/// [ScannerService.decodeImageFile] — on a real device or emulator, but
/// with no live camera or human scanning involved. This exercises the
/// actual ML Kit integration (ADR 0003) deterministically.
///
/// Run with: `flutter test integration_test/barcode_scan_test.dart`
/// (needs a connected device or a running emulator — this cannot run in
/// plain `flutter test`/CI without one).
void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  // Keep in sync with app/lib/data/seed_catalog.dart and
  // tool/generate_barcode_fixtures.py.
  const expectedCodes = [
    '100000000014',
    '100000000021',
    '100000000038',
    '100000000045',
    '100000000052',
    '100000000069',
    '100000000076',
    '100000000083',
    '100000000090',
    '100000000106',
    '100000000113',
    '100000000120',
    '999999999993', // deliberately not in the seed catalog (SCAN-8 case)
  ];

  late ScannerService scanner;

  setUp(() {
    scanner = ScannerService();
  });

  tearDown(() async {
    await scanner.dispose();
  });

  for (final code in expectedCodes) {
    testWidgets('decodes fixture $code.png correctly', (tester) async {
      final path = await _copyFixtureToTempFile(code);
      final decoded = await scanner.decodeImageFile(path);
      expect(decoded, code);
    });
  }
}

Future<String> _copyFixtureToTempFile(String code) async {
  final data = await rootBundle.load('test/fixtures/barcodes/$code.png');
  final dir = await getTemporaryDirectory();
  final file = File('${dir.path}/$code.png');
  await file.writeAsBytes(data.buffer.asUint8List());
  return file.path;
}
